const raw = $input.first().json;
const msg = raw.message || {};
const adminId = String($env.ADMIN_TELEGRAM_ID || '0');
const senderId = String(msg.from?.id || '');
const chatId = String(msg.chat?.id || '');
const firstName = msg.from?.first_name || 'Irmão(ã)';
const text = String(msg.text || msg.caption || '').trim();
const fileId = msg.voice?.file_id || msg.audio?.file_id || msg.video_note?.file_id || null;
const hadVoice = !text && !!fileId;
return [{ json: {
  adminId, senderId, chatId, firstName,
  text: text || (hadVoice ? '' : '[mensagem sem texto]'),
  hadVoice, fileId: fileId || '',
  voiceError: ''
} }];

const prep = $('Preparar (texto/voz)').first().json;
const j = $input.first().json || {};
let text = String(j.text || '').trim();
let voiceError = '';
if (!text) {
  voiceError = String(j.error?.message || j.message || 'whisper vazio').slice(0, 180);
  text = '[áudio recebido, mas não consegui transcrever]';
}
return [{ json: { ...prep, text, hadVoice: true, voiceError } }];

const prev = $input.first().json;
const base = String($env.CK_BASE_URL || 'https://www.conectaking.com.br').replace(/\/$/, '');
const token = String($env.CK_AGENT_JWT || '').trim();
const openaiKey = String($env.OPENAI_API_KEY || '').trim();
const model = String($env.OPENAI_MODEL || 'gpt-4o-mini').trim();
const text = String(prev.text || '').trim();
const chatId = String(prev.chatId || '');
const hadVoice = !!prev.hadVoice;
const firstName = String(prev.firstName || 'Irmão(ã)');

// HTTP helper para Conecta King API
async function ck(method, path, body) {
  const opts = {
    method,
    url: base + path,
    headers: {
      'Accept': 'application/json',
      'Content-Type': 'application/json',
      ...(token ? { 'Authorization': 'Bearer ' + token } : {})
    },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  };
  if (body !== undefined) opts.body = body;
  return this.helpers.httpRequest.call(this, opts);
}

// HTTP helper para OpenAI API
async function openaiCall(payload) {
  return this.helpers.httpRequest.call(this, {
    method: 'POST',
    url: 'https://api.openai.com/v1/chat/completions',
    headers: {
      'Authorization': 'Bearer ' + openaiKey,
      'Accept': 'application/json',
      'Content-Type': 'application/json'
    },
    body: payload,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true
  });
}

// Armazenamento de memória no staticData global
const store = $getWorkflowStaticData('global');
if (!store.chats) store.chats = {};
if (!store.chats[chatId]) {
  store.chats[chatId] = { history: [] };
}
const session = store.chats[chatId];
if (!session.history) session.history = [];

const SYSTEM_PROMPT = `Você é o Agente Bíblia da Conecta King no Telegram (@AgenteBiblia_Bot).
Você é um conselheiro bíblico, teológico e espiritual de excelência, dedicado EXCLUSIVAMENTE às Sagradas Escrituras, fé, devocionais, sabedoria cristã e princípios de Deus.

TOM DE VOZ:
- Acolhedor, reverente, inspirador, sábio e profundamente fundamentado na Bíblia.
- Linguagem clara, elegante em Português do Brasil, sem jargões frios de robô.
- Use emojis com bom gosto (📖, 🕊️, ✨, 🙏, 👑, 🌿, 💡).
- Quando citar a Bíblia, mencione o Livro, Capítulo e Versículo com precisão.

SEUS PRINCIPAIS RECURSOS & FERRAMENTAS:
1. 'get_verse_of_day': Obter o versículo oficial do dia da Conecta King com reflexão.
2. 'get_devocional_do_dia': Obter o devocional diário com meditação prática.
3. 'get_salmo_do_dia': Obter a leitura e consolo do Salmo do dia.
4. 'get_prosperidade_hoje': Obter o princípio diário das 365 ativações de Prosperidade Bíblica da plataforma.
5. 'get_bible_text': Consultar capítulos ou passagens bíblicas.
6. 'generate_sermon_outline': Criar esboços completos de sermões/pregações com introdução, tópicos e aplicação prática.
7. 'pastoral_prayer_counsel': Conduzir orações pastorais e aconselhamento bíblico para ansiedade, decisões, família, gratidão ou trabalho.

IMPORTANTE:
- Responda apenas sobre a Bíblia, fé cristã, edificação espiritual e as ferramentas bíblicas.
- Se o usuário pedir serviços de fotografia, finanças ou assuntos administrativos do King, oriente com carinho que para esses temas ele deve usar o @AgenteKingBot no canal principal.`;

const TOOLS = [
  {
    type: 'function',
    function: {
      name: 'get_verse_of_day',
      description: 'Retorna o Versículo do Dia cadastrado na Conecta King com texto sagrado e reflexão.',
      parameters: {
        type: 'object',
        properties: {
          date: { type: 'string', description: 'Data opcional no formato YYYY-MM-DD' }
        }
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'get_devocional_do_dia',
      description: 'Retorna o Devocional do Dia da plataforma Conecta King.',
      parameters: {
        type: 'object',
        properties: {
          date: { type: 'string', description: 'Data opcional no formato YYYY-MM-DD' }
        }
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'get_salmo_do_dia',
      description: 'Retorna o Salmo do Dia com oração e meditação de louvor/conforto.',
      parameters: {
        type: 'object',
        properties: {}
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'get_prosperidade_hoje',
      description: 'Retorna a ativação do dia do projeto 365 Ativações de Prosperidade Bíblica Conecta King.',
      parameters: {
        type: 'object',
        properties: {
          day: { type: 'number', description: 'Número do dia opcional (1 a 365)' }
        }
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'get_bible_text',
      description: 'Busca o texto bíblico de um livro e capítulo específico (ex: Genesis 1, Salmos 23, Joao 3).',
      parameters: {
        type: 'object',
        properties: {
          book_id: { type: 'string', description: 'Identificador do livro (ex: genesis, exodo, salmos, proverbios, mateus, joao, romanos)' },
          chapter: { type: 'number', description: 'Número do capítulo' }
        },
        required: ['book_id', 'chapter']
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'generate_sermon_outline',
      description: 'Gera um esboço expositivo de sermão ou pregação para ministrar.',
      parameters: {
        type: 'object',
        properties: {
          theme: { type: 'string', description: 'Tema ou título da mensagem' },
          passage: { type: 'string', description: 'Passagem ou texto bíblico base' },
          audience: { type: 'string', description: 'Público-alvo (jovens, igreja, liderança, família)' }
        },
        required: ['theme']
      }
    }
  },
  {
    type: 'function',
    function: {
      name: 'pastoral_prayer_counsel',
      description: 'Gera uma oração pastoral e conselho bíblico personalizado para o momento da pessoa.',
      parameters: {
        type: 'object',
        properties: {
          need: { type: 'string', description: 'Motivo da oração (saúde, paz, família, direção, gratidão, finanças, ansiedade)' },
          name: { type: 'string', description: 'Nome da pessoa para incluir na oração' }
        },
        required: ['need']
      }
    }
  }
];

let outMessage = '';

try {
  if (!openaiKey) {
    // Fallback gracioso se a OpenAI Key não estiver setada
    const r = await ck.call(this, 'GET', '/api/bible/verse-of-day');
    const v = (r.body && r.body.data) || {};
    outMessage = `🕊️ *A paz do Senhor, ${firstName}!*\n\n📖 *Versículo do Dia:*\n_"${v.texto || 'O Senhor é o meu pastor; de nada terei falta.'}"_\n— *${v.ref || 'Salmos 23:1'}*\n\n✨ _${v.reflexao || 'Confie no cuidado e na provisão divina para o seu dia.'}_\n\nComo posso orar ou estudar a Palavra com você hoje?`;
  } else {
    const inputForAi = (hadVoice ? '[áudio transcrito] ' : '') + (text || 'A paz do Senhor!');
    const messages = [
      { role: 'system', content: SYSTEM_PROMPT },
      ...session.history.slice(-6),
      { role: 'user', content: inputForAi }
    ];

    const completionRes = await openaiCall.call(this, {
      model,
      temperature: 0.3,
      messages,
      tools: TOOLS,
      tool_choice: 'auto'
    });

    const choice = completionRes.body?.choices?.[0]?.message;

    if (choice?.tool_calls && choice.tool_calls.length > 0) {
      const toolCall = choice.tool_calls[0];
      const fnName = toolCall.function.name;
      let args = {};
      try { args = JSON.parse(toolCall.function.arguments || '{}'); } catch (_) {}

      if (fnName === 'get_verse_of_day') {
        const query = args.date ? '?date=' + encodeURIComponent(args.date) : '';
        const r = await ck.call(this, 'GET', '/api/bible/verse-of-day' + query);
        const data = (r.body && r.body.data) || {};
        const ref = data.ref || 'Palavra do Dia';
        const versiculo = data.texto || 'Lâmpada para os meus pés é tua palavra e luz, para o meu caminho. (Salmos 119:105)';
        const reflexao = data.reflexao || 'Guarde esta promessa em seu coração e permita que ela guie suas decisões hoje.';

        outMessage = `📖 *Versículo do Dia | Conecta King*\n\n"*${versiculo}*"\n\n📍 *${ref}*\n\n🕊️ *Reflexão:*\n${reflexao}\n\nQue esta Palavra alimente o seu espírito hoje! 🙏`;
      } else if (fnName === 'get_devocional_do_dia') {
        const r = await ck.call(this, 'GET', '/api/bible/devocional-do-dia');
        const d = (r.body && r.body.data) || {};
        const titulo = d.titulo || d.title || 'Devocional Diário';
        const passagem = d.passagem || d.reference || d.ref || 'Escrituras Sagradas';
        const texto = d.texto || d.content || d.meditacao || '';
        const oracao = d.oracao || d.prayer || '';

        outMessage = `✨ *Devocional do Dia:* ${titulo}\n\n📖 *Texto Base:* ${passagem}\n\n${texto}\n\n${oracao ? '🙏 *Oração:*\n_' + oracao + '_\n\n' : ''}Amém! Que Deus abençoe sua jornada.`;
      } else if (fnName === 'get_salmo_do_dia') {
        const r = await ck.call(this, 'GET', '/api/bible/salmo-do-dia');
        const s = (r.body && r.body.data) || {};
        const ref = s.ref || 'Salmos';
        const texto = s.texto || '';
        const reflexao = s.reflexao || '';

        outMessage = `🛡️ *Salmo do Dia:* ${ref}\n\n"${texto}"\n\n${reflexao ? '🕊️ *Meditação:*\n' + reflexao + '\n\n' : ''}Que o Senhor seja o seu refúgio e fortaleza hoje! 🙌`;
      } else if (fnName === 'get_prosperidade_hoje') {
        const path = args.day ? '/api/bible/prosperidade/ativacao/' + args.day : '/api/bible/prosperidade/hoje';
        const r = await ck.call(this, 'GET', path);
        const p = (r.body && r.body.data) || {};
        const num = p.numero || p.day || p.dia || '365';
        const titulo = p.titulo || p.title || 'Ativação Bíblica de Prosperidade';
        const versiculo = p.versiculo || p.verse || '';
        const declaracao = p.declaracao || p.affirmation || '';
        const chave = p.chave || p.chave_prosperidade || p.principio || '';
        const acao = p.acao_pratica || p.action || '';

        outMessage = `👑 *Ativação de Prosperidade Bíblica #${num}*\n\n💎 *${titulo}*\n\n📖 *Princípio Bíblico:*\n"${versiculo}"\n\n${chave ? '🔑 *Chave de Sabedoria:* ' + chave + '\n\n' : ''}${declaracao ? '🗣️ *Declaração de Fé:*\n_"' + declaracao + '"_\n\n' : ''}${acao ? '🎯 *Passo Prático de Hoje:* ' + acao + '\n\n' : ''}Deus tem prazer na prosperidade integral da sua vida!`;
      } else if (fnName === 'get_bible_text') {
        const bookId = String(args.book_id || 'salmos').toLowerCase();
        const cap = Number(args.chapter || 1);
        const r = await ck.call(this, 'GET', `/api/bible/book/${bookId}/${cap}`);
        const data = (r.body && r.body.data) || {};
        const bookName = data.book?.name || bookId.toUpperCase();
        const verses = data.verses || data.versiculos || [];

        if (Array.isArray(verses) && verses.length > 0) {
          const sample = verses.slice(0, 10).map(v => `*${v.number || v.verse}* ${v.text}`).join('\n\n');
          outMessage = `📖 *${bookName} ${cap}*\n\n${sample}${verses.length > 10 ? '\n\n_(Exibindo os primeiros 10 versículos de ' + verses.length + ')_' : ''}`;
        } else {
          outMessage = `📖 *Leitura de ${bookName} ${cap}* consultada na plataforma. Deseja uma reflexão teológica ou estudo guiado sobre este capítulo?`;
        }
      } else if (fnName === 'generate_sermon_outline') {
        const theme = args.theme;
        const pass = args.passage || 'Escrituras';
        const aud = args.audience ? ` (Público: ${args.audience})` : '';

        // Segunda chamada para gerar o esboço com profundidade
        const sermonRes = await openaiCall.call(this, {
          model,
          temperature: 0.4,
          messages: [
            { role: 'system', content: 'Você é um pregador e mestre bíblico expositivo. Crie um esboço claro de sermão contendo: 1. Título impactante; 2. Texto Base com contexto; 3. Introdução que prenda a atenção; 4. Três pontos principais expositivos bem alicerçados nas escrituras; 5. Aplicação prática para o cotidiano; 6. Conclusão e apelo/oração.' },
            { role: 'user', content: `Elabore um esboço de pregação sobre o tema: "${theme}", baseado em "${pass}"${aud}.` }
          ]
        });
        outMessage = sermonRes.body?.choices?.[0]?.message?.content || `📋 *Esboço de Pregação: ${theme}*\n\n📖 Base: ${pass}\n\nDeus ministre através de você!`;
      } else if (fnName === 'pastoral_prayer_counsel') {
        const prayerRes = await openaiCall.call(this, {
          model,
          temperature: 0.4,
          messages: [
            { role: 'system', content: 'Você é um pastor acolhedor e cheio de fé. Escreva uma oração pastoral profunda, sincera e bíblica, trazendo consolo, esperança e paz ao coração da pessoa, finalizando com uma bênção sacerdotal.' },
            { role: 'user', content: `Faça uma oração pastoral para ${args.name || firstName}, que necessita de intercessão e direção sobre: ${args.need}.` }
          ]
        });
        outMessage = prayerRes.body?.choices?.[0]?.message?.content || `🙏 Que a paz que excede todo entendimento guarde o seu coração em Cristo Jesus.`;
      }
    } else {
      outMessage = choice?.content || `A paz do Senhor, ${firstName}! Estou aqui para estudarmos as Escrituras, orarmos e compartilharmos a sabedoria da Palavra de Deus.`;
    }

    session.history.push({ role: 'user', content: inputForAi });
    session.history.push({ role: 'assistant', content: outMessage });
    if (session.history.length > 12) session.history.splice(0, 2);
  }
} catch (e) {
  outMessage = '🕊️ Graça e Paz! Ocorreu uma oscilação momentânea: ' + String(e.message || e).slice(0, 200) + '\n\nComo posso abençoar seus estudos na Palavra hoje?';
}

return [{ json: { ...prev, outMessage } }];
